-- Lease Audit: automatic re-check of the open findings at every refresh (Riyadh GL only; STATUS<>'C' = cancelled excluded).
-- Output R: key;a;b;c   keys: LEGOP (2123001 balance at 31-Dec of previous year) | LEG (2123001 balance at window end) | CC (voucher;account;cost centres) | D09 (chairman residence vouchers: voucher;status;amount)
--          D11 (warehouse accrual: yyyymm;amount) | S0290 (supplier balance) | DOC (distinct in-scope vouchers with an attachment; {VL} = in-scope list)
SELECT 'LEGOP;'||ROUND(SUM(CR_AMOUNT-DR_AMOUNT),2)||';;' R FROM {P}GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='2123001' AND STATUS='P' AND VM_DATE<DATE '{Y0}'
UNION ALL SELECT 'LEG;'||ROUND(SUM(CR_AMOUNT-DR_AMOUNT),2)||';;' FROM {P}GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='2123001' AND STATUS='P' AND VM_DATE<DATE '{D1}'
UNION ALL SELECT 'CC;'||VOUCHER_NO||';'||ACCOUNT_NO||';'||MIN(COST_CENTER_NO)||'/'||MAX(COST_CENTER_NO) FROM {P}GL_TRANSACTIONS_DETAILS WHERE VOUCHER_NO IN ({GV}) AND STATUS<>'C' AND ACCOUNT_NO IN ('4300003','2123001') GROUP BY VOUCHER_NO, ACCOUNT_NO
UNION ALL SELECT 'D09;'||VOUCHER_NO||';'||STATUS||';'||ROUND(SUM(DR_AMOUNT),2) FROM {P}GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='3230000' AND STATUS<>'C' AND VM_DATE>=DATE '2026-05-21' AND DESCRIPTION LIKE '%رئيس مجلس%' GROUP BY VOUCHER_NO, STATUS
UNION ALL SELECT 'D11;'||TO_CHAR(VM_DATE,'YYYYMM')||';'||ROUND(SUM(DR_AMOUNT),2)||';' FROM {P}GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='3230000' AND STATUS<>'C' AND VM_DATE>=DATE '2026-06-01' AND (DESCRIPTION LIKE '%مستودع%' OR DESCRIPTION LIKE '%مخزن%') GROUP BY TO_CHAR(VM_DATE,'YYYYMM')
UNION ALL SELECT 'S0290;'||ROUND(SUM(CR_AMOUNT-DR_AMOUNT),2)||';;' FROM {P}GL_TRANSACTIONS_DETAILS WHERE ACCOUNT_NO='2122001' AND SUB_ACCOUNT_NO='S0290' AND STATUS<>'C'
UNION ALL SELECT 'DOC;'||COUNT(DISTINCT VOUCHER_NO)||';;' FROM {P}VOUCHER_ATTACH WHERE VOUCHER_NO IN ({VL})
